{
  "arguments": [
    {
      "claim": "The Drennick team’s use of the red cross emblem on the van and on their uniforms constitutes improper use of a distinctive emblem, which is a war crime under the Rome Statute.",
      "reasoning": "Article 8(b)(vii) of the Rome Statute criminalises \"Making improper use of ... the distinctive emblems of the Geneva Conventions, resulting in death or serious personal injury.\" The van was marked with a red cross – a protected emblem under the Geneva Conventions – yet the vehicle was not engaged in medical duties and was used to deceive the Calvaran soldiers, leading to their deaths and injuries. This conduct therefore satisfies the elements of the offence.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "Making improper use of a flag of truce, of the flag or of the military insignia and uniform of the enemy or of the United Nations, as well as of the distinctive emblems of the Geneva Conventions, resulting in death or serious personal injury;"
        }
      ]
    },
    {
      "claim": "The killing of the Calvaran soldiers who had laid down their weapons violates the protection afforded to persons hors de combat under Geneva Convention IV and constitutes wilful killing, a grave breach and war crime.",
      "reasoning": "Geneva Convention IV, article 3 expressly protects \"persons taking no active part in the hostilities, including members of armed forces who have laid down their arms and those placed 'hors de combat'\" and prohibits \"violence to life and person, in particular murder of all kinds.\" At the checkpoint the Calvaran soldiers lowered their weapons and approached the van, thereby becoming hors de combat. The Drennick team’s subsequent opening fire resulted in their murder, satisfying the prohibition. Under article 8(b)(i) of the Rome Statute, \"Wilful killing\" is a war crime, and the facts meet that element.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "gc_iv",
          "article": "3",
          "quoted_text": "Persons taking no active part in the hostilities, including members of armed forces who have laid down their arms and those placed 'hors de combat' ... shall ... be treated humanely ... The following acts are ... prohibited ... (a) violence to life and person, in particular murder of all kinds, ..."
        },
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "Wilful killing;"
        }
      ]
    }
  ]
}
